INSERT  IGNORE INTO `tbl_email_layout` (`id`, `header`, `footer`, `name`) VALUES (1,'&lt;!DOCTYPE html PUBLIC &quot;-//W3C//DTD XHTML 1.0 Transitional//EN&quot; &quot;http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd&quot;&gt;\r\n&lt;html xmlns=&quot;http://www.w3.org/1999/xhtml&quot;&gt;\r\n&lt;head&gt;\r\n&lt;title&gt;{$companeyname}&lt;/title&gt;\r\n&lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=UTF-8&quot; /&gt;\r\n&lt;/head&gt;\r\n&lt;body style=&quot;margin:0;background: #f4f4f4;&quot;&gt;\r\n\r\n&lt;div class=&quot;bg&quot;&gt;\r\n\r\n&lt;table  style=&quot;color:#153643;font-size:14px;width:100%;font-family: Open Sans, Helvetica, Arial, sans-serif;border:none;border-spacing:0;&quot;&gt;&lt;tr&gt;&lt;td&gt;\r\n{literal}\r\n&lt;style&gt;\r\n    .bg {\r\n		background: #f4f4f4;\r\n		padding:20px;\r\n		margin:50px 0;\r\n    }     \r\n    @media only screen and (max-width: 600px)\r\n    {\r\n		.bg {\r\n			background: #fff;\r\n			padding:0;\r\n		}   \r\n    }\r\n&lt;/style&gt;\r\n{/literal}\r\n	&lt;div  style=&quot;margin-left: auto;  margin-right: auto;  max-width:850px;background: #ffffff;&quot;&gt;\r\n		&lt;div style=&quot;background-color: #0F015E;background-image: radial-gradient(farthest-corner at 50% 100%, rgba(123,22,255,0.75),#0F015E );&quot;&gt;\r\n	 \r\n			&lt;div  style=&quot;padding:40px;text-align:center;color:#153643;font-weight: normal;font-size:20px;&quot;&gt;\r\n				&lt;h3 style=&quot;margin:0;color:white&quot;&gt;\r\n					{$companyname}\r\n				&lt;/h3&gt;\r\n			&lt;/div&gt;\r\n			 \r\n		&lt;/div&gt;\r\n		\r\n		\r\n		&lt;div   style=&quot;padding:20px;&quot;&gt;\r\n		 \r\n		  ',' &lt;/div&gt;\r\n		&lt;div class=&quot;footer&quot; style=&quot;color:#777;padding:20px;background: #fff;text-align:center;font-size:13px&quot;&gt;			\r\n			&lt;div style=&quot;border-top:#ddd solid 1px;&quot;&gt;\r\n			\r\n			&lt;div style=&quot;max-width:500px;margin:auto;text-align:center&quot;&gt;\r\n			&lt;div style=&quot;padding:20px&quot;&gt;\r\n				&lt;ul style=&quot;padding:0;margin:0;&quot;&gt;\r\n					&lt;li style=&quot;list-style: none;display: inline-block;font-weight: bold;&quot;&gt;\r\n						&lt;a href=&quot;{$siteaddress}&quot; target=&quot;_blank&quot; style=&quot;text-decoration: none;color:#0F015E;padding:10px&quot;&gt;\r\n							Home\r\n						&lt;/a&gt;\r\n					&lt;/li&gt;\r\n					&lt;li style=&quot;list-style: none;display: inline-block;font-weight: bold;&quot;&gt;\r\n						&lt;a style=&quot;text-decoration: none;color:#0F015E;padding:10px&quot; href=&quot;{$siteaddress}/contact.php&quot;  target=&quot;_blank&quot;&gt;\r\n							Contact Us\r\n						&lt;/a&gt;\r\n					&lt;/li&gt;\r\n				&lt;/ul&gt;\r\n			&lt;/div&gt;\r\n			\r\n			 \r\n				&lt;div&gt;                    \r\n               If you don\'t want to receive these emails in the future, you may update your subscription preferences or   &lt;a href=&quot;{$siteaddress}/index.php?u={$enc}&quot; style=&quot;text-decoration: none;color:#999&quot;&gt;Unsubscribe&lt;/a&gt; from all emails. \r\n            &lt;/div&gt;\r\n			\r\n			\r\n			&lt;div style=&quot;padding:10px&quot;&gt;\r\n				&amp;copy;{$companyname} 	all rights reserved. 			\r\n			&lt;/div&gt;	\r\n						 \r\n			 \r\n			&lt;div   style=&quot;text-align:center;&quot;&gt;\r\n				{if $twitter} &lt;span&gt;\r\n				&lt;a href=&quot;http://www.twitter.com/{$twitter}&quot;   style=&quot;background-position:-68px 0;background-image:url(\'{$siteaddress}/images/social-icon.png \');background-repeat:no-repeat;display:inline-block;height:35px;margin:2px;width:35px;&quot;&gt;\r\n				&lt;/a&gt;\r\n				&lt;/span&gt;{/if}                                                   \r\n				{if $facebook} &lt;span&gt;\r\n				&lt;a href=&quot;http://www.facebook.com/{$facebook}&quot;   style=&quot;background-position:-35px 0;background-image:url(\'{$siteaddress}/images/social-icon.png \');background-repeat:no-repeat;display:inline-block;height:35px;margin:2px;width:35px;&quot;&gt;\r\n				&lt;/a&gt;\r\n				&lt;/span&gt;{/if}           \r\n				{if $linkedin} &lt;span&gt;\r\n				&lt;a href=&quot;{$linkedin}&quot;  style=&quot;background-position:-102px 0;background-image:url(\'{$siteaddress}/images/social-icon.png \');background-repeat:no-repeat;display:inline-block;height:35px;margin:2px;width:35px;&quot;&gt;\r\n				&lt;/a&gt;\r\n				&lt;/span&gt;{/if}  \r\n				{if $resellerstore} &lt;span&gt;\r\n				&lt;a href=&quot;viewrss.php&quot;   style=&quot;background-position:-3px 0;background-image:url(\'{$siteaddress}/images/social-icon.png \');background-repeat:no-repeat;display:inline-block;height:35px;margin:2px;width:35px;&quot;&gt;\r\n				&lt;/a&gt;\r\n				&lt;/span&gt;{/if}\r\n			&lt;/div&gt;\r\n		&lt;/div&gt;\r\n		\r\n		&lt;/div&gt;\r\n		\r\n		&lt;/div&gt;\r\n	&lt;/div&gt;\r\n	\r\n	\r\n	&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;\r\n	\r\n&lt;/div&gt;\r\n	\r\n&lt;/body&gt;\r\n&lt;/html&gt;\r\n ','default');
